    public interface MyBatisBuilders {
        /**
         * MyBatis (camel-mybatis)
         * Query, insert, update or delete rows in a relational database, or
         * poll it for rows, with MyBatis mapped statements.
         * 
         * Category: database
         * Since: 2.7
         * Maven coordinates: org.apache.camel:camel-mybatis
         * 
         * @return the dsl builder for the headers' name.
         */
        default MyBatisHeaderNameBuilder mybatis() {
            return MyBatisHeaderNameBuilder.INSTANCE;
        }
        /**
         * MyBatis (camel-mybatis)
         * Query, insert, update or delete rows in a relational database, or
         * poll it for rows, with MyBatis mapped statements.
         * 
         * Category: database
         * Since: 2.7
         * Maven coordinates: org.apache.camel:camel-mybatis
         * 
         * Syntax: <code>mybatis:statement</code>
         * 
         * Path parameter: statement (required)
         * The ID of the mapped statement to run, as a mapper XML file or a
         * mapper annotation of the MyBatis configuration declares it, for
         * example selectAllAccounts, or qualified by its namespace. The
         * consumer runs it as a select without parameter on each poll, and the
         * producer as the statementType option says.
         * 
         * @param path statement
         * @return the dsl builder
         */
        default MyBatisEndpointBuilder mybatis(String path) {
            return MyBatisEndpointBuilderFactory.endpointBuilder("mybatis", path);
        }
        /**
         * MyBatis (camel-mybatis)
         * Query, insert, update or delete rows in a relational database, or
         * poll it for rows, with MyBatis mapped statements.
         * 
         * Category: database
         * Since: 2.7
         * Maven coordinates: org.apache.camel:camel-mybatis
         * 
         * Syntax: <code>mybatis:statement</code>
         * 
         * Path parameter: statement (required)
         * The ID of the mapped statement to run, as a mapper XML file or a
         * mapper annotation of the MyBatis configuration declares it, for
         * example selectAllAccounts, or qualified by its namespace. The
         * consumer runs it as a select without parameter on each poll, and the
         * producer as the statementType option says.
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path statement
         * @return the dsl builder
         */
        default MyBatisEndpointBuilder mybatis(String componentName, String path) {
            return MyBatisEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
    /**
     * The builder of headers' name for the MyBatis component.
     */
    public static class MyBatisHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final MyBatisHeaderNameBuilder INSTANCE = new MyBatisHeaderNameBuilder();

        /**
         * The result that the producer sets: the row or the List of rows of a
         * select, the count of rows of an insert, update or delete (of the last
         * run for a List), or for mybatis-bean what the method returns. A
         * generated key is not in it: MyBatis sets that key on the parameter
         * object. With outputHeader, the result is in that header instead.
         * 
         * The option is a: {@code Object} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code MyBatisResult}.
         */
        public String myBatisResult() {
            return "CamelMyBatisResult";
        }
        /**
         * The ID of the mapped statement that ran, from the statement option,
         * for example insertAccount. The consumer and the producer set it.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: common
         * 
         * @return the name of the header {@code MyBatisStatementName}.
         */
        public String myBatisStatementName() {
            return "CamelMyBatisStatementName";
        }
    }
    static MyBatisEndpointBuilder endpointBuilder(String componentName, String path) {
        class MyBatisEndpointBuilderImpl extends AbstractEndpointBuilder implements MyBatisEndpointBuilder, AdvancedMyBatisEndpointBuilder {
            public MyBatisEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new MyBatisEndpointBuilderImpl(path);
    }
